// Channel profiles: which scenery a SomaFM channel starts its journey in.
// profiles.json is generated by scripts/build-profiles.mjs; do not edit by hand.
import profiles from './profiles.json';

// Returns { biomes, level } for a channel id, or the default for unknown/missing ids.
export function getProfile(channelId) {
  const known = channelId && channelId !== '_default' && Object.prototype.hasOwnProperty.call(profiles, channelId);
  const p = known ? profiles[channelId] : profiles._default;
  return { biomes: [...p.biomes], level: p.level };
}
